import { useState, FormEvent } from 'react';
import { JxInputField, JxSelect, JxSwitch, JxButton, JxAlert } from '@jinx-ui/react';

const ROLE_OPTIONS = [
  { value: 'viewer', label: 'Наблюдатель' },
  { value: 'editor', label: 'Редактор' },
  { value: 'admin', label: 'Администратор' },
];

const EMAIL_PATTERN = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;

export default function TeamInviteForm() {
  const [email, setEmail] = useState('');
  const [role, setRole] = useState('editor');
  const [notify, setNotify] = useState(true);
  const [invited, setInvited] = useState(false);

  const emailInvalid = email.length > 0 && !EMAIL_PATTERN.test(email);
  const canSubmit = email.length > 0 && !emailInvalid;

  const handleSubmit = (event: FormEvent<HTMLFormElement>) => {
    event.preventDefault();
    if (!canSubmit) return;
    setInvited(true);
  };

  return (
    <div style={{ display: 'flex', flexDirection: 'column', gap: '16px', maxWidth: '360px' }}>
      {invited && (
        <div style={{ display: 'flex', alignItems: 'flex-start', gap: '8px' }}>
          <div style={{ flex: 1 }}>
            <JxAlert intent="success" title="Приглашение отправлено">
              Мы отправили приглашение на {email}.
            </JxAlert>
          </div>
          <JxButton
            iconOnly
            variant="ghost"
            size="sm"
            type="button"
            aria-label="Закрыть сообщение"
            onClick={() => setInvited(false)}
          >
            ×
          </JxButton>
        </div>
      )}

      <form onSubmit={handleSubmit} style={{ display: 'flex', flexDirection: 'column', gap: '16px' }}>
        <JxInputField
          label="Электронная почта"
          type="email"
          required
          placeholder="name@company.com"
          value={email}
          onChange={(event) => setEmail(event.target.value)}
          errorText={emailInvalid ? 'Введите адрес в формате name@company.com' : undefined}
          helperText={!emailInvalid ? 'Мы отправим приглашение на этот адрес' : undefined}
        />

        <JxSelect
          label="Роль"
          options={ROLE_OPTIONS}
          value={role}
          onValueChange={setRole}
        />

        <JxSwitch
          label="Отправить уведомление на почту"
          checked={notify}
          onChange={(event) => setNotify(event.target.checked)}
        />

        <JxButton type="submit" variant="primary" disabled={!canSubmit}>
          Пригласить
        </JxButton>
      </form>
    </div>
  );
}

